'use strict';
const assert=require('node:assert/strict'),path=require('node:path'),fs=require('node:fs');
async function qualifyListingsCatalogRendered({app,origin,adapter,auth,config,progress,identity,student,admin,scope,projection}){
 const root=process.env.LISTINGS_EVIDENCE_ROOT,key='secureshop_agent_security',id='ss_listing_generated_browser_execution',pass=(_q,_s,next)=>next();
 const authRouter=require('../../server/routes/postgresAuth').createPostgresAuthRouter({adapter,limiters:{loginRateLimiter:pass,registerRateLimiter:pass,passwordResetRateLimiter:pass}});
 app.use('/api/auth',authRouter);app.use('/api/changes',require('../../server/routes/changeRevisions').createChangeRevisionsRouter({store:require('../../server/database/postgres/workshopRevisionRepository').createWorkshopRevisionStore(identity),authenticateToken:auth.authenticateToken}));app.use('/api/admin',require('../../server/routes/postgresAdmin').createPostgresAdminRouter({adapter,stores:{pool:identity,progress,config},auth}));app.get('/api/ctf/config',(_q,res)=>res.json({enabled:false,show_in_nav:false}));app.use('/api',(_q,res)=>res.status(404).json({error:'Outside Listings catalog fixture'}));const build=path.join(process.cwd(),'client/build');app.use(require('express').static(build));app.get(/.*/,(_q,res)=>res.sendFile('index.html',{root:build}));
 process.env.ANALYTICS_BROWSER_EXECUTABLE=path.join(require('node:os').homedir(),'.cache/puppeteer/chrome-headless-shell/mac_arm-152.0.7977.75/chrome-headless-shell-mac-arm64/chrome-headless-shell');process.env.ANALYTICS_BROWSER_SHA256=require('./fullBackendRenderedBranch').BROWSER_SHA;
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'listingsparity'),errors=[],blocked=[],screenshots=[];
 const configure=async(page,token)=>{await page.setViewport({width:1440,height:1050});await require('./fullBackendRenderedSecureShop').configurePage(page,origin,blocked,errors,token);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);};
 try{
  const page=await browser.newPage();await configure(page,student.token);
  for(const route of ['/workshop-dashboard','/workshop/challenges','/workshop/progress']){await page.goto(origin+route,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>document.body.innerText.includes('SecureShop Agent Security')&&/1\s*\/\s*4|1 of 4/.test(document.body.innerText));assert.ok((await page.$eval('body',el=>el.innerText)).includes(route==='/workshop/challenges'?'< 1m':projection.timeSpentSeconds+'s'));if(route==='/workshop/progress')assert.equal(new URL(page.url()).pathname,'/workshop-dashboard');}
  const screenshot=async(page,name)=>{await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));const file=name+'.png';await page.screenshot({path:path.join(root,file),fullPage:true});screenshots.push(file);};await screenshot(page,'listings-learner-dashboard');
  await page.goto(origin+'/workshop/challenges');await page.waitForFunction(()=>document.body.innerText.includes('1/4 completed'));
  await page.evaluate(()=>[...document.querySelectorAll('button')].find(b=>b.textContent.includes('Show all 4 objectives'))?.click());
  const completionStyle=await page.evaluate(()=>{const text='Save model-generated listing HTML and observe its attributed browser execution';const label=[...document.querySelectorAll('span')].find(e=>e.textContent===text);if(!label)return null;const row=label.parentElement.parentElement;return{hasCheck:!!row.querySelector('svg'),color:getComputedStyle(label).color};});assert.ok(completionStyle?.hasCheck);assert.equal(completionStyle.color,'rgb(45, 106, 79)');await screenshot(page,'listings-learner-objectives');
  const context=await browser.createBrowserContext(),adminPage=await context.newPage();await configure(adminPage,admin.token);await adminPage.goto(origin+'/admin/exercises');const card='[data-exercise-key="'+key+'"]';await adminPage.waitForSelector(card);
  const click=async(selector)=>{await adminPage.$eval(selector,el=>el.scrollIntoView({block:'center'}));await adminPage.waitForFunction(selector=>{const el=document.querySelector(selector);if(!el)return false;const r=el.getBoundingClientRect(),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return hit===el||el.contains(hit);},{},selector);await adminPage.click(selector);};
  const gate=async(field,value)=>adminPage.waitForFunction(async(field,value)=>{const body=await(await fetch('/api/workshop/config/snapshot')).json();return body.exercises.secureshop_agent_security[field]===value;},{},field,value);
  await click(card+' [data-control="solutions"]');await gate('showSolutions',false);await page.goto(origin+'/workshop/challenges');await page.waitForFunction(()=>[...document.querySelectorAll('button')].some(b=>b.textContent.trim()==='Hint'));assert.equal(await page.$$eval('button',els=>els.some(e=>e.textContent.trim()==='Solution')),false);
  await click(card+' [data-control="solutions"]');await gate('showSolutions',true);await click(card+' [data-control="hints"]');await gate('showHints',false);await page.goto(origin+'/workshop/challenges');await page.waitForFunction(()=>[...document.querySelectorAll('button')].some(b=>b.textContent.trim()==='Solution'));assert.equal(await page.$$eval('button',els=>els.some(e=>e.textContent.trim()==='Hint')),false);
  await adminPage.$eval(card,el=>[...el.querySelectorAll('button')].find(b=>b.textContent.includes('Manage Objectives')).click());const row='[data-objective-id="'+id+'"]';await adminPage.waitForSelector(row);assert.ok(await adminPage.$(row+' [title="Preview Solution"]'));await screenshot(adminPage,'listings-admin-controls');
  await click(row+' [data-control="visible"]');await page.goto(origin+'/workshop/challenges');await page.waitForFunction(()=>document.body.innerText.includes('0/3'));await click(row+' [data-control="visible"]');await page.goto(origin+'/workshop-dashboard');await page.waitForFunction(()=>document.body.innerText.includes('1/4'));
  await adminPage.goto(origin+'/admin/student-workshop-view?studentId='+scope.platformOwnerId);await adminPage.waitForFunction(()=>document.body.innerText.includes('SecureShop Agent Security')&&/1\s*\/\s*4|1 of 4/.test(document.body.innerText));assert.ok((await adminPage.$eval('body',el=>el.innerText)).includes(projection.timeSpentSeconds+'s'));await screenshot(adminPage,'listings-admin-student');
  assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);
  return{status:'passed',actualReactApp:true,canonicalHttpApi:true,candidateCatalogOnly:true,controlledDisplayCompletion:true,actualModelCalls:0,projection,completionStyle,screenshots,checks:['dashboard/challenges/progress redirect counts and nonzero time','completed objective rendered','admin controls toggle independent hints and solutions','objective visibility changes learner count and completion denominator','admin student view parity']};
 }catch(error){for(const [index,page]of(await browser.pages()).entries()){await page.screenshot({path:path.join(root,'listings-parity-failure-'+index+'.png'),fullPage:true}).catch(()=>{});}fs.writeFileSync(path.join(root,'listings-parity-browser-errors.json'),JSON.stringify({errors,blocked,message:error.message}),{mode:0o600});throw error;}finally{await browser.close();authRouter.close();}
}
module.exports={qualifyListingsCatalogRendered};
